syntax:
template< class K >
std::pair<iterator, iterator> equal_range( const K& value ) const;
// Implementation notes: This function is typically defined in the container's class (e.g., std::set). It calls lower_bound to find the first element not less than 'value' and upper_bound to find the first element greater than 'value'. The compiler may optimize this by inlining the binary search logic, reducing function call overhead. For custom comparators, the compiler generates code that incorporates the comparator function into the search loop.

code_example:
#include <set>
#include <iostream>

int main() {
    std::set<int> s = {1, 2, 2, 3, 4};  // Red-black tree-based container
    auto range = s.equal_range(2);  // Returns pair of iterators to the range [2, 2]
    for (auto it = range.first; it != range.second; ++it) {
        std::cout << *it << std::endl;  // Outputs: 2
    }
    return 0;
}
